ALTER TABLE public.regulatory_sources ADD COLUMN regulation_number text, ADD COLUMN legal_version text, ADD COLUMN legal_version_date date, ADD COLUMN celex_id text, ADD COLUMN library_catalog boolean NOT NULL DEFAULT false, ADD COLUMN version_note text, ADD COLUMN imported_at timestamptz;
ALTER TABLE public.regulatory_requirements ADD COLUMN article_reference text, ADD COLUMN annex_reference text, ADD COLUMN required_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN verification_status text NOT NULL DEFAULT 'UNVERIFIED' CHECK (verification_status IN ('UNVERIFIED','VERIFIED')), ADD COLUMN wording_sha256 text, ADD COLUMN imported_at timestamptz;
CREATE POLICY source_catalog_read ON public.regulatory_sources FOR SELECT TO authenticated USING (library_catalog AND organization_id IS NULL);
CREATE OR REPLACE FUNCTION public.catalog_assessment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.regulatory_sources WHERE id=NEW.regulatory_source_id AND library_catalog) AND (NOT EXISTS(SELECT 1 FROM public.regulatory_requirements WHERE regulatory_source_id=NEW.regulatory_source_id AND rule_set_version=NEW.rule_set_version) OR EXISTS(SELECT 1 FROM public.regulatory_requirements WHERE regulatory_source_id=NEW.regulatory_source_id AND rule_set_version=NEW.rule_set_version AND (verification_status<>'VERIFIED' OR status<>'active'))) THEN RAISE EXCEPTION 'Unverified imported requirements cannot be used in formal assessments';END IF;RETURN NEW;END $$;
CREATE TRIGGER catalog_assessment_verification BEFORE INSERT OR UPDATE ON public.compliance_assessments FOR EACH ROW EXECUTE FUNCTION public.catalog_assessment_guard();
COMMENT ON COLUMN public.regulatory_requirements.required_evidence IS 'Engineering evidence checklist, not quoted legal wording; requires review.';
COMMENT ON COLUMN public.regulatory_sources.legal_version IS 'Pinned legal edition; never implies latest consolidated law.';